INSERT INTO `act_hi_detail` VALUES ('47a972a1-d9d6-11ee-805f-6a8acb6bfd7e', 'VariableUpdate', '1afcd542-d9d6-11ee-805f-6a8acb6bfd7e', '1afcd542-d9d6-11ee-805f-6a8acb6bfd7e', NULL, NULL, 'description', 'string', 1, '2024-03-04 11:21:24.358', NULL, NULL, NULL, '<ul><li><strong>需求来源</strong><span style=\"color: rgb(191, 191, 191);\"><em>（需求提出人名称|所属部门|职务|反馈方式）</em></span></li></ul><p style=\"text-align: start; line-height: 1.5;\">1.需求来源人：内部</p><p style=\"text-align: start; line-height: 1.5;\">2.来源时间：2024-1-29</p><ul><li><strong>需求内容</strong><span style=\"color: rgb(191, 191, 191);\"><em>（客户/用户需求哪些产品特性|期望交付时间）</em></span></li></ul><p style=\"text-align: start; line-height: 1.5;\">优化领导人尊称识别：</p><p style=\"text-align: start; line-height: 1.5;\">1、对领导表进行优化：补充单字领导的其他尊称信息，若“赵云”，赵总-赵云，云总-赵总；</p><p style=\"text-align: start; line-height: 1.5;\"> ===需要提供领导表</p><p style=\"text-align: start; line-height: 1.5;\">2、只查询当前部门，不再向上查询；</p><p style=\"text-align: start; line-height: 1.5;\"> </p><ul><li><strong>需求价值</strong><span style=\"color: rgb(191, 191, 191);\"><em>（做了需求会有那哪些价值|不做会有哪些问题）</em></span></li></ul><p>1、 提升客户满意度，优化操作交互和用户体验</p><ul><li><strong>验收标准</strong><span style=\"color: rgb(191, 191, 191);\"><em>（需求验收有哪些标准）</em></span></li></ul><p style=\"text-align: start; line-height: 1.5;\">1,测试xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx</p>', NULL);
