INSERT INTO `act_hi_detail` VALUES ('a7f7b328-f08c-11ee-be2f-020e9076b254', 'VariableUpdate', '360383c9-efd0-11ee-be2f-020e9076b254', '36050a97-efd0-11ee-be2f-020e9076b254', '360de471-efd0-11ee-be2f-020e9076b254', NULL, 'priorityId', 'string', 1, '2024-04-02 09:02:19.918', NULL, NULL, NULL, '2', NULL);
