INSERT INTO `act_ru_variable` VALUES ('4fde5100-10fb-11ef-810a-be0287f21d38', 1, 'string', 'description', '4fdb1ca8-10fb-11ef-810a-be0287f21d38', '4fdb1ca8-10fb-11ef-810a-be0287f21d38', NULL, NULL, NULL, NULL, '<p><br></p><p>•<em><strong>需求来源（需求提出人名称|所属部门|职务|反馈方式）</strong></em></p><p style=\"text-align: start; line-height: 1.5;\">宋文锦/综合管理部/产品经理/</p><p style=\"text-align: start; line-height: 1.5;\">•<em><strong>需求内容（客户/用户需求哪些产品特性|期望交付时间）</strong></em></p><p style=\"text-align: start; line-height: 1.5;\">nginx版本号隐藏/2024-04-25</p><p style=\"text-align: start; line-height: 1.5;\">•<em><strong>需求价值（做了需求会有那哪些价值|不做会有哪些问题）</strong></em></p><p style=\"text-align: start; line-height: 1.5;\"> 系统安全问题</p><p style=\"text-align: start; line-height: 1.5;\">•<em><strong>验收标准（需求验收有哪些标准）</strong></em></p><p style=\"text-align: start; line-height: 1.5;\"> 生产环境首页测试</p><p style=\"text-align: start; line-height: 1.5;\"> </p><p> </p>', NULL);
