INSERT INTO `bpm_task_ext` VALUES (4, '[1]', '发起人节点', '168c135b-d94a-11ee-a84a-6a9db2f28e92', 2, '自动通过', '2024-03-03 18:37:53', '1687cd68-d94a-11ee-a84a-6a9db2f28e92', 'Activity_1x4mvbo', '7026eac0-68fc-11ee-abe2-ea47a4de657a', '1', '2024-03-03 18:37:52', '1', '2024-03-03 18:37:53', b'0', 0, '{\"businessDemandSource\":null,\"belongToProject\":null,\"expectHours\":null,\"endDate\":null,\"developStyle\":null,\"tagIds\":null,\"$assignedIds\":\"超级管理员 | 项目经理\",\"description\":\"<p>研发需求描述</p><p>一、原始需求描述：</p><p>1.需求来源人：交易管理部-李炎骅</p><p>2.来源时间：2023.12.15</p><p>3.内容：一柜通反洗钱相关名单监控优化。个人户、机构户、产品户开户及客户资料变更，对公客户受益所有人、投权统办人、法定代表人、控股股东或实际控制人等重要关系人纳入实时监测范围。移动一柜通同步修改</p><p>4.目的：为了满足监管要求，对相关关系人进行监控优化。</p><p>二、用户需求描述： </p><p>1.用户对象：一柜通柜员登录一柜通系统，帮助客户办理业务</p><p>2.具体场景： 办理经纪业务开户/客户资料变更/非临柜-客户资料变更（管理）业务时，填写相关重要关系人三要素（姓名、证件类型、证件号码）信息后，判断是是否在交易所重点监控账户、中登账户实名制名单、道琼斯黑名单、反洗钱中高风险客户4种监测类型名单中，若是，则给出警示，点击下一步，同时弹出温馨提示，移动一柜通也许同步优化。</p><p>三、验收标准：</p><p>1、业务正常受理和审核</p><p>2、业务影像资料正常归档</p><p><br></p>\",\"title\":\"【迭代】反洗钱相关重要关系人名单监控优化\",\"demandStage\":\"1\",\"prototype\":null,\"priorityId\":\"2\",\"shareProjects\":null,\"file\":null,\"statusId\":\"6\",\"belongToModule\":null,\"demandClass\":null,\"requirementProposer\":null,\"demandOfDepartment\":null,\"candidateList\":\"[1]\",\"assignedIds\":\"1,2856704057914482688\",\"$priorityId\":\"中\",\"isChange\":\"0\",\"assignerDepartment\":null}', NULL, '{\"bpmUserTaskPermissions\":[{\"通过\":{\"buttonPermission\":1}},{\"不通过\":{\"buttonPermission\":1}}]}', NULL, 0, NULL);
