INSERT INTO `bpm_task_ext` VALUES (22, '[2856704057914482688]', '发起人节点', '20e2a26e-db64-11ee-a16e-7e2214c79bf6', 2, '自动通过', '2024-03-06 10:49:19', '20d50dab-db64-11ee-a16e-7e2214c79bf6', 'Activity_1x4mvbo', '7026eac0-68fc-11ee-abe2-ea47a4de657a', '2856704057914482688', '2024-03-06 10:49:19', '2856704057914482688', '2024-03-06 10:49:20', b'0', 0, '{\"businessDemandSource\":\"飞书\",\"belongToProject\":\"2\",\"expectHours\":null,\"endDate\":\"2024-03-05\",\"developStyle\":null,\"tagIds\":null,\"$assignedIds\":\"项目经理 | 超级管理员\",\"description\":\"<ul><li><strong>需求来源</strong><span style=\\\"color: rgb(191, 191, 191);\\\"><em>（需求提出人名称|所属部门|职务|反馈方式）</em></span></li></ul><p style=\\\"text-align: start; line-height: 1.5;\\\">1.需求来源人：交易管理部-李炎骅</p><p style=\\\"text-align: start; line-height: 1.5;\\\">2.来源时间：2023.12.15</p><ul><li><strong>需求内容</strong><span style=\\\"color: rgb(191, 191, 191);\\\"><em>（客户/用户需求哪些产品特性|期望交付时间）</em></span></li></ul><p style=\\\"text-align: start; line-height: 1.5;\\\">一、需求描述： </p><p style=\\\"text-align: start; line-height: 1.5;\\\">1.内容：一柜通反洗钱相关名单监控优化。个人户、机构户、产品户开户及客户资料变更，对公客户受益所有人、投权统办人、法定代表人、控股股东或实际控制人等重要关系人纳入实时监测范围。移动一柜通同步修改</p><p style=\\\"text-align: start; line-height: 1.5;\\\">2.目的：为了满足监管要求，对相关关系人进行监控优化。</p><p style=\\\"text-align: start; line-height: 1.5;\\\">二、用户需求描述： </p><p style=\\\"text-align: start; line-height: 1.5;\\\">1.用户对象：一柜通柜员登录一柜通系统，帮助客户办理业务</p><p style=\\\"text-align: start; line-height: 1.5;\\\">2.具体场景： 办理经纪业务开户/客户资料变更/非临柜-客户资料变更（管理）业务时，填写相关重要关系人三要素（姓名、证件类型、证件号码）信息后，判断是是否在交易所重点监控账户、中登账户实名制名单、道琼斯黑名单、反洗钱中高风险客户4种监测类型名单中，若是，则给出警示，点击下一步，同时弹出温馨提示，移动一柜通也许同步优化。</p><ul><li><strong>需求价值</strong><span style=\\\"color: rgb(191, 191, 191);\\\"><em>（做了需求会有那哪些价值|不做会有哪些问题）</em></span></li></ul><p> 优化用户体验xxxxxxxxxxxxxx</p><ul><li><strong>验收标准</strong><span style=\\\"color: rgb(191, 191, 191);\\\"><em>（需求验收有哪些标准）</em></span></li></ul><p style=\\\"text-align: start; line-height: 1.5;\\\">1、业务正常受理和审核</p><p style=\\\"text-align: start; line-height: 1.5;\\\">2、业务影像资料正常归档</p>\",\"title\":\"【业务需求】优化一柜台\",\"demandStage\":\"1\",\"prototype\":null,\"priorityId\":\"2\",\"shareProjects\":null,\"file\":null,\"statusId\":\"6\",\"belongToModule\":\"1\",\"demandClass\":\"功能\",\"requirementProposer\":\"2856704057914482688\",\"demandOfDepartment\":null,\"candidateList\":\"[2856704057914482688]\",\"assignedIds\":\"2856704057914482688,1\",\"$priorityId\":\"中\",\"isChange\":\"0\",\"assignerDepartment\":null}', NULL, '{\"bpmUserTaskPermissions\":[{\"通过\":{\"buttonPermission\":1}},{\"不通过\":{\"buttonPermission\":1}}]}', NULL, 0, NULL);
